From d3c552fc79284767731d47dd87f22a0bc1d5a990 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 03:47:17 +0100
Subject: [PATCH] shell/scripting: give the widget the value writeConfig writes
 to the file

writeConfig() gave the raw script value to the widget, so a string with
commas for a list key became one bogus entry until a restart parsed the
file. The value is now written first and read back with the item's type.

BUG: 446739
---
 shell/scripting/applet.cpp | 5 +++--
 1 file changed, 3 insertions(+), 2 deletions(-)

diff --git a/shell/scripting/applet.cpp b/shell/scripting/applet.cpp
index 9b69e32f93..a9e7b76ac8 100644
--- a/shell/scripting/applet.cpp
+++ b/shell/scripting/applet.cpp
@@ -101,6 +101,8 @@ QVariant Applet::readConfig(const QString &key, const QJSValue &def) const
 void Applet::writeConfig(const QString &key, const QJSValue &value)
 {
     if (d->configGroup.isValid()) {
+        d->configGroup.writeEntry(key, value.toVariant());
+
         if (d->inWallpaperConfig) {
             // hacky, but only way to make the wallpaper react immediately
             auto *wallpaperGraphicsObject = applet()->property("wallpaperGraphicsObject").value<QObject *>();
@@ -111,7 +113,7 @@ void Applet::writeConfig(const QString &key, const QJSValue &value)
         } else if (KConfigLoader *configScheme = applet()->configScheme()) {
             // check if it can be written in the applets' configScheme
             if (KConfigSkeletonItem *item = configScheme->findItemByName(key)) {
-                item->setProperty(value.toVariant());
+                item->setProperty(d->configGroup.readEntry(key, item->property()));
                 configScheme->blockSignals(true);
                 configScheme->save();
                 // why read? read will update KConfigSkeletonItem::mLoadedValue,
@@ -122,7 +124,6 @@ void Applet::writeConfig(const QString &key, const QJSValue &value)
             }
         }

-        d->configGroup.writeEntry(key, value.toVariant());
         d->configDirty = true;
     }
 }
